import re
MESSAGE = re.compile(r"(?P<time>\d\d:\d\d) (?P<name>\w+): ")
lines = [input() for n in range(int(input()))]
for line in lines:
    m = MESSAGE.match(line)
    if m:
        print(f"{m['name']} at {m['time']}")
for line in lines:
    print(re.sub(r"\d\d:\d\d", "??:??", line))
